arguments.command:
cat > pol.py <<'E'
import sys,json
from m import *
def V(p,d):
    ev=float(p@pay); best=(max(ev,0),'approve' if ev>0 else 'decline')
    if d==0: return best
    for c in C:
        t=0
        for b in range(6):
            w=p*P[c][:,b]; pb=w.sum(); 
            if pb<1e-9: continue
            t+=pb*V(w/pb,d-1)[0]
        t-=20
        if t>best[0]: best=(t,c)
    return best
if __name__=='__main__':
    prior=np.array(json.loads(sys.argv[1])); p=prior.copy()
    for h in sys.argv[2:]:
        c,b=h.split(':'); w=p*P[c][:,int(b)]; p=w/w.sum()
    print(np.round(p,3),'EV',round(float(p@pay)),V(p,3))
